import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import {
  type FormEvent,
  type ReactNode,
  useEffect,
  useRef,
  useState,
} from "react";
import { z } from "zod";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  correctSighting,
  deleteSighting,
  getSighting,
} from "@/lib/sighting-functions";
import {
  type CorrectSighting,
  correctSightingInputSchema,
  DELETE_FAILURE_MESSAGE,
  type DeleteSighting,
  DONENESS_VALUES,
  type GetSighting,
  RECENT_SIGHTINGS_FAILURE_MESSAGE,
  SIGHTING_NOT_FOUND_MESSAGE,
  type Sighting,
} from "@/lib/sightings";

export const Route = createFileRoute("/sightings/$sightingId")({
  component: CorrectionRoute,
  validateSearch: z.object({
    from: z.enum(["capture", "completion"]).catch("capture"),
  }),
});

const LABEL_TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
type CorrectionFields = {
  doneness: Sighting["doneness"];
  labelDate: string;
  labelTime: string;
};

function labelMinuteToTime(labelMinute: number): string {
  const hour = Math.floor(labelMinute / 60);
  const minute = labelMinute % 60;

  return `${hour.toString().padStart(2, "0")}:${minute.toString().padStart(2, "0")}`;
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = LABEL_TIME_PATTERN.exec(labelTime);
  if (!match) {
    return undefined;
  }

  return Number(match[1]) * 60 + Number(match[2]);
}

function correctionFieldsFromSighting(sighting: Sighting): CorrectionFields {
  return {
    doneness: sighting.doneness,
    labelDate: sighting.labelDate,
    labelTime: labelMinuteToTime(sighting.labelMinute),
  };
}

function getFocusTarget(isLoading: boolean, isNotFound: boolean): string {
  if (isLoading) {
    return "loading";
  }

  return isNotFound ? "not-found" : "editor";
}

export function CorrectionRoute(): ReactNode {
  const { sightingId } = Route.useParams();
  const { from } = Route.useSearch();
  const navigate = useNavigate();
  const correct = useServerFn(correctSighting);
  const remove = useServerFn(deleteSighting);
  const get = useServerFn(getSighting);
  const id = Number(sightingId);
  const returnToOrigin = async (
    preserveCompletion: boolean,
    sighting?: Sighting
  ): Promise<void> => {
    await navigate({
      search:
        preserveCompletion && from === "completion"
          ? { completion: sighting?.id ?? id }
          : {},
      to: "/",
    });
  };

  return (
    <CorrectionEditor
      correctSighting={async (input) => await correct({ data: input })}
      deleteSighting={async (deleteId) => await remove({ data: deleteId })}
      getSighting={async (getId) => await get({ data: getId })}
      id={id}
      onCancel={async () => await returnToOrigin(true)}
      onDeleted={async () => await returnToOrigin(false)}
      onNotFoundReturn={async () => await returnToOrigin(false)}
      onSaved={async (sighting) => await returnToOrigin(true, sighting)}
    />
  );
}

export function CorrectionEditor({
  correctSighting,
  deleteSighting,
  getSighting,
  id,
  onCancel,
  onDeleted,
  onNotFoundReturn,
  onSaved,
}: Readonly<{
  correctSighting: CorrectSighting;
  deleteSighting: DeleteSighting;
  getSighting: GetSighting;
  id: number;
  onCancel: () => Promise<void>;
  onDeleted: () => Promise<void>;
  onNotFoundReturn: () => Promise<void>;
  onSaved: (sighting: Sighting) => Promise<void>;
}>): ReactNode {
  const headingRef = useRef<HTMLHeadingElement>(null);
  const confirmationRef = useRef<HTMLHeadingElement>(null);
  const [fields, setFields] = useState<CorrectionFields>();
  const [errorMessage, setErrorMessage] = useState<string>();
  const [isConfirmingDeletion, setIsConfirmingDeletion] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isNotFound, setIsNotFound] = useState(false);
  const [loadAttempt, setLoadAttempt] = useState(0);

  const focusTarget = getFocusTarget(isLoading, isNotFound);

  useEffect(() => {
    if (focusTarget !== "loading") {
      headingRef.current?.focus();
    }
  }, [focusTarget]);

  useEffect(() => {
    if (!Number.isInteger(id) || id < 1) {
      setIsLoading(false);
      setIsNotFound(true);
      return;
    }

    let active = true;
    if (loadAttempt > 0) {
      setFields(undefined);
      setIsNotFound(false);
    }
    const markLoadUnavailable = (): void => {
      if (active) {
        setErrorMessage(RECENT_SIGHTINGS_FAILURE_MESSAGE);
      }
    };
    const loadSighting = async (): Promise<void> => {
      setIsLoading(true);
      setErrorMessage(undefined);
      try {
        const result = await getSighting(id);
        if (!active) {
          return;
        }

        if (!result.ok) {
          setIsNotFound(result.kind === "not-found");
          setErrorMessage(
            result.kind === "not-found" ? undefined : result.message
          );
          return;
        }

        setFields(correctionFieldsFromSighting(result.sighting));
        setIsNotFound(false);
      } catch {
        markLoadUnavailable();
      } finally {
        if (active) {
          setIsLoading(false);
        }
      }
    };

    loadSighting().catch(markLoadUnavailable);
    return () => {
      active = false;
    };
  }, [getSighting, id, loadAttempt]);

  const updateFields = (next: Partial<CorrectionFields>): void => {
    setFields((current) => (current ? { ...current, ...next } : current));
  };

  const saveCorrection = async (): Promise<void> => {
    if (!fields || isSaving || isDeleting) {
      return;
    }

    const labelMinute = labelTimeToMinute(fields.labelTime);
    if (labelMinute === undefined) {
      setErrorMessage("Enter a complete clock time.");
      return;
    }

    const validation = correctSightingInputSchema.safeParse({
      doneness: fields.doneness,
      id,
      labelDate: fields.labelDate,
      labelMinute,
    });
    if (!validation.success) {
      setErrorMessage("Enter a complete real date.");
      return;
    }

    setErrorMessage(undefined);
    setIsSaving(true);
    try {
      const result = await correctSighting(validation.data);
      if (!result.ok) {
        if (result.kind === "not-found") {
          setIsNotFound(true);
          return;
        }

        setErrorMessage(result.message);
        return;
      }

      await onSaved(result.sighting);
    } catch {
      setErrorMessage("Unable to save this correction. Try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const confirmDeletion = async (): Promise<void> => {
    if (isDeleting || isSaving) {
      return;
    }

    setErrorMessage(undefined);
    setIsDeleting(true);
    try {
      const result = await deleteSighting(id);
      if (!result.ok) {
        if (result.kind === "not-found") {
          setIsNotFound(true);
          setIsConfirmingDeletion(false);
          return;
        }

        setErrorMessage(result.message);
        return;
      }

      await onDeleted();
    } catch {
      setErrorMessage(DELETE_FAILURE_MESSAGE);
    } finally {
      setIsDeleting(false);
    }
  };

  const handleSubmit = async (
    event: FormEvent<HTMLFormElement>
  ): Promise<void> => {
    event.preventDefault();
    await saveCorrection();
  };

  const returnWithoutSaving = async (
    returnToOrigin: () => Promise<void>
  ): Promise<void> => {
    try {
      await returnToOrigin();
    } catch {
      setErrorMessage("Unable to return to Capture. Try again.");
    }
  };

  if (isLoading) {
    return (
      <CorrectionFrame heading="Correct sighting">
        Loading sighting…
      </CorrectionFrame>
    );
  }

  if (isNotFound) {
    return (
      <CorrectionFrame heading="Sighting not found" headingRef={headingRef}>
        <p className="text-muted-foreground">{SIGHTING_NOT_FOUND_MESSAGE}</p>
        <Button
          className="mt-6 h-12 text-base"
          onClick={async () => await returnWithoutSaving(onNotFoundReturn)}
          type="button"
        >
          Return to Capture
        </Button>
      </CorrectionFrame>
    );
  }

  if (!fields) {
    return (
      <CorrectionFrame heading="Correct sighting" headingRef={headingRef}>
        <p className="text-destructive" role="alert">
          {errorMessage ?? RECENT_SIGHTINGS_FAILURE_MESSAGE}
        </p>
        <Button
          className="mt-6 h-12 text-base"
          onClick={() => setLoadAttempt((attempt) => attempt + 1)}
          type="button"
        >
          Try again
        </Button>
        <Button
          className="mt-3 h-12 text-base"
          onClick={async () => await returnWithoutSaving(onCancel)}
          type="button"
          variant="outline"
        >
          Cancel
        </Button>
      </CorrectionFrame>
    );
  }

  return (
    <CorrectionFrame heading="Correct sighting" headingRef={headingRef}>
      <Card>
        <CardHeader>
          <CardTitle>Label facts</CardTitle>
        </CardHeader>
        <CardContent>
          <form className="grid gap-6" noValidate onSubmit={handleSubmit}>
            <div className="grid gap-2">
              <Label htmlFor="correction-label-time">Label time</Label>
              <Input
                className="h-16 text-3xl"
                id="correction-label-time"
                onChange={(event) =>
                  updateFields({ labelTime: event.target.value })
                }
                required
                type="time"
                value={fields.labelTime}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="correction-label-date">Label date</Label>
              <Input
                id="correction-label-date"
import "@testing-library/jest-dom/vitest";

import {
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { CorrectionEditor } from "@/app/sightings/$sightingId";
import type {
  CorrectSighting,
  DeleteSighting,
  GetSighting,
  Sighting,
} from "@/lib/sightings";

const DEFAULT_SIGHTING: Sighting = {
  createdAt: new Date("2026-08-11T19:05:00.000Z"),
  doneness: "dark",
  id: 7,
  labelDate: "2026-08-11",
  labelMinute: 845,
  updatedAt: new Date("2026-08-11T19:05:00.000Z"),
};

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

function renderCorrection({
  correctSighting = vi.fn(),
  deleteSighting = vi.fn(),
  getSighting = vi.fn().mockResolvedValue({
    ok: true,
    sighting: DEFAULT_SIGHTING,
  }),
  onCancel = vi.fn(),
  onDeleted = vi.fn(),
  onNotFoundReturn = vi.fn(),
  onSaved = vi.fn(),
}: Partial<{
  correctSighting: CorrectSighting;
  deleteSighting: DeleteSighting;
  getSighting: GetSighting;
  onCancel: () => Promise<void>;
  onDeleted: () => Promise<void>;
  onNotFoundReturn: () => Promise<void>;
  onSaved: (sighting: Sighting) => Promise<void>;
}> = {}): {
  correctSighting: CorrectSighting;
  deleteSighting: DeleteSighting;
  getSighting: GetSighting;
  onCancel: () => Promise<void>;
  onDeleted: () => Promise<void>;
  onNotFoundReturn: () => Promise<void>;
  onSaved: (sighting: Sighting) => Promise<void>;
} {
  render(
    <CorrectionEditor
      correctSighting={correctSighting}
      deleteSighting={deleteSighting}
      getSighting={getSighting}
      id={DEFAULT_SIGHTING.id}
      onCancel={onCancel}
      onDeleted={onDeleted}
      onNotFoundReturn={onNotFoundReturn}
      onSaved={onSaved}
    />
  );

  return {
    correctSighting,
    deleteSighting,
    getSighting,
    onCancel,
    onDeleted,
    onNotFoundReturn,
    onSaved,
  };
}

describe("Correction", () => {
  it("loads an identity-addressed sighting into a keyboard-focused full-screen editor", async () => {
    renderCorrection();

    await screen.findByLabelText("Label date");
    const heading = screen.getByRole("heading", { name: "Correct sighting" });
    await waitFor(() => {
      expect(heading).toHaveFocus();
    });
    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
    expect(screen.getByLabelText("Label time")).toHaveValue("14:05");
    expect(screen.getByLabelText("Doneness")).toHaveValue("dark");
    expect(
      screen.getByRole("button", { name: "Save correction" })
    ).toBeTruthy();
  });

  it("replaces label facts and nullable doneness together, then returns the persisted sighting", async () => {
    const correctedSighting = {
      ...DEFAULT_SIGHTING,
      doneness: null,
      labelDate: "2024-02-29",
      labelMinute: 480,
      updatedAt: new Date("2026-08-11T19:10:00.000Z"),
    };
    const correctSighting = vi.fn().mockResolvedValue({
      ok: true,
      sighting: correctedSighting,
    });
    const { onSaved } = renderCorrection({ correctSighting });

    await screen.findByLabelText("Label date");
    fireEvent.change(screen.getByLabelText("Label date"), {
      target: { value: "2024-02-29" },
    });
    fireEvent.change(screen.getByLabelText("Label time"), {
      target: { value: "08:00" },
    });
    fireEvent.change(screen.getByLabelText("Doneness"), {
      target: { value: "" },
    });
    fireEvent.click(screen.getByRole("button", { name: "Save correction" }));

    await waitFor(() => {
      expect(correctSighting).toHaveBeenCalledWith({
        doneness: null,
        id: 7,
        labelDate: "2024-02-29",
        labelMinute: 480,
      });
    });
    expect(onSaved).toHaveBeenCalledWith(correctedSighting);
  });

  it("cancels without mutating the sighting", async () => {
    const { correctSighting, deleteSighting, onCancel } = renderCorrection();

    await screen.findByLabelText("Label date");
    fireEvent.click(screen.getByRole("button", { name: "Cancel" }));

    expect(onCancel).toHaveBeenCalledTimes(1);
    expect(correctSighting).not.toHaveBeenCalled();
    expect(deleteSighting).not.toHaveBeenCalled();
  });

  it("keeps the loaded editor available when Cancel cannot return to Capture", async () => {
    const onCancel = vi
      .fn<() => Promise<void>>()
      .mockRejectedValue(new Error("Navigation unavailable"));
    const { correctSighting, deleteSighting } = renderCorrection({ onCancel });

    await screen.findByLabelText("Label date");
    fireEvent.click(screen.getByRole("button", { name: "Cancel" }));

    await waitFor(() => {
      expect(screen.getByRole("alert")).toHaveTextContent(
        "Unable to return to Capture. Try again."
      );
    });
    expect(onCancel).toHaveBeenCalledTimes(1);
    expect(correctSighting).not.toHaveBeenCalled();
    expect(deleteSighting).not.toHaveBeenCalled();
    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
    expect(screen.getByRole("button", { name: "Cancel" })).toBeEnabled();
  });

  it("keeps corrected facts visible after a correction failure and provides a retry path", async () => {
    const correctSighting = vi.fn().mockResolvedValue({
      kind: "unavailable",
      message: "Unable to save this correction. Try again.",
      ok: false,
    });
    renderCorrection({ correctSighting });

    await screen.findByLabelText("Label date");
    fireEvent.change(screen.getByLabelText("Label time"), {
      target: { value: "08:00" },
    });
    fireEvent.click(screen.getByRole("button", { name: "Save correction" }));

    await waitFor(() => {
      expect(screen.getByRole("alert")).toHaveTextContent(
        "Unable to save this correction"
      );
    });
    expect(screen.getByLabelText("Label time")).toHaveValue("08:00");
    expect(
      screen.getByRole("button", { name: "Save correction" })
    ).toBeEnabled();
  });

  it("shows a stable not-found state for a missing identity", async () => {
    renderCorrection({
      getSighting: vi.fn().mockResolvedValue({
        kind: "not-found",
        message: "This sighting is no longer available.",
        ok: false,
      }),
    });

    expect(
      await screen.findByRole("heading", { name: "Sighting not found" })
    ).toBeTruthy();
    expect(
      screen.getByText("This sighting is no longer available.")
    ).toBeTruthy();
    expect(
      screen.getByRole("button", { name: "Return to Capture" })
    ).toBeTruthy();
    expect(screen.queryByLabelText("Label date")).toBeNull();
  });

  it("requires confirmation before hard deletion and lets the tracker cancel it", async () => {
    const { deleteSighting } = renderCorrection();

    await screen.findByLabelText("Label date");
    fireEvent.click(screen.getByRole("button", { name: "Delete sighting" }));
    const confirmation = screen.getByRole("dialog");
    expect(confirmation).toBeTruthy();
    expect(
      screen.getByRole("heading", { name: "Permanently delete this sighting?" })
    ).toHaveFocus();
    fireEvent.click(screen.getByRole("button", { name: "Keep sighting" }));

    expect(deleteSighting).not.toHaveBeenCalled();
    await waitFor(() => {
      expect(screen.queryByRole("dialog")).toBeNull();
    });
    expect(
      screen.getByRole("button", { name: "Delete sighting" })
    ).toHaveFocus();
    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
  });

  it("deletes permanently only after confirmation and returns to the origin", async () => {
    const deleteSighting = vi.fn().mockResolvedValue({ ok: true });
    const { onDeleted } = renderCorrection({ deleteSighting });

    await screen.findByLabelText("Label date");
    fireEvent.click(screen.getByRole("button", { name: "Delete sighting" }));
    fireEvent.click(screen.getByRole("button", { name: "Permanently delete" }));

    await waitFor(() => {
      expect(deleteSighting).toHaveBeenCalledWith(7);
    });
    expect(onDeleted).toHaveBeenCalledTimes(1);
  });

  it("keeps the editor and sighting visible when deletion fails", async () => {
    const deleteSighting = vi.fn().mockResolvedValue({
      kind: "unavailable",
      message: "Unable to delete this sighting. Try again.",
      ok: false,
    });
    renderCorrection({ deleteSighting });

    await screen.findByLabelText("Label date");
    fireEvent.click(screen.getByRole("button", { name: "Delete sighting" }));
    fireEvent.click(screen.getByRole("button", { name: "Permanently delete" }));

    await waitFor(() => {
      expect(screen.getByRole("alert")).toHaveTextContent(
        "Unable to delete this sighting"
      );
    });
    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
    expect(screen.getByRole("dialog")).toBeTruthy();
  });
});
